from six import string_types
from .time_converter import TimeConverter


def to_boolean(item):
    """ Convert given value to boolean True or False

    Examples of values that convert to True:
    True, "True", "true", "TRUE", "Yes", "yes", "YES", 1

    Examples of values that convert to False:
    False, "False", "false", "FALSE", "No", "no", "NO", 0
    """
    if isinstance(item, string_types):
        item = item.lower()
        if item == "true" or item == "yes":
            item = True
        elif item == "false" or item == "no":
            item = False
    else:
        item = bool(item)

    return item


def time_to_seconds(time, round_to=None):
    """ Convert given time value to a number of seconds

    Parameter `time` can be:
    - None - makes the function return None
    - a number (of seconds) given as integer (3), a float (3.0)
    or a string ('3', '3.0')
    - a time string
    Time strings are strings in format like 1 minute 42 seconds or 1min 42s.
    The basic idea of this format is having first a number and then a text
    specifying what time that number represents.
    Numbers can be either integers or floating point numbers, the whole format
    is case and space insensitive, and it is possible to add a minus prefix to
    specify negative times

    The available time specifiers are:
    - days, day, d
    - hours, hour, h
    - minutes, minute, mins, min, m
    - seconds, second, secs, sec, s
    - milliseconds, millisecond, millis, ms

    By default, returned number is not rounded. If `round_to` parameter is
    a number, then the returned number will be rounded up to that number of
    decimal digits. Note that when `round_to` is equal to 0, the returned
    number will be an integer.

    All example below return the same output: 4800.0.
    >>> time_to_seconds('4800')
    >>> time_to_seconds('4800.0')
    >>> time_to_seconds('4800 s')
    >>> time_to_seconds('1h20m')
    >>> time_to_seconds('1 H 20 M')
    >>> time_to_seconds('1 hours 20mins')
    >>> time_to_seconds('1 hour 20 min 0 secs 0.0 ms')
    >>> time_to_seconds('79 min 59 secs 990.0 ms', round_to=1)

    Note that a non-None input is valid if either all numbers have
    corresponding time components or there is only one number.
    That said, the following input is invalid and results in ValueError:
    >>> time_to_seconds('10m 2')
    ValueError: Invalid time string '10m 2'.
    """
    return TimeConverter.to_seconds(time, round_to=round_to)
